function normLon(lon) {
  let l = ((lon + 180) % 360 + 360) % 360 - 180;
  if (l === -180 && lon > 0) l = 180;
  return l;
}

function decodeRing(arr, w, h) {
  const pts = [];
  let x = 0;
  let y = 0;
  for (let i = 0; i < arr.length; i += 2) {
    x += arr[i];
    y += arr[i + 1];
    const lon = (x / w) * 360 - 180;
    const lat = 90 - (y / h) * 180;
    const prev = pts[pts.length - 1];
    if (!prev || prev[0] !== lon || prev[1] !== lat) {
      pts.push([lon, lat]);
    }
  }
  if (pts.length > 2) {
    const first = pts[0];
    const last = pts[pts.length - 1];
    if (first[0] === last[0] && first[1] === last[1]) {
      pts.pop();
    }
  }
  return pts;
}

function unwrapRing(ring) {
  if (!ring.length) return [];
  const out = [[ring[0][0], ring[0][1]]];
  let prevLon = ring[0][0];
  for (let i = 1; i < ring.length; i++) {
    let lon = ring[i][0];
    let diff = lon - prevLon;
    while (diff > 180) { lon -= 360; diff -= 360; }
    while (diff < -180) { lon += 360; diff += 360; }
    out.push([lon, ring[i][1]]);
    prevLon = lon;
  }
  return out;
}

// Exact spherical polygon area (steradians) via van Oosterom & Strackee solid angle
function ringSphericalAreaSr(ring) {
  const n = ring.length;
  if (n < 3) return 0;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    const p1 = ring[i];
    const p2 = ring[(i + 1) % n];
    if (p1[0] === p2[0] && p1[1] === p2[1]) continue;
    const lat1 = p1[1] * DEG2RAD;
    const lat2 = p2[1] * DEG2RAD;
    const dLon = (p2[0] - p1[0]) * DEG2RAD;
    const c1 = Math.cos(lat1), s1 = Math.sin(lat1);
    const c2 = Math.cos(lat2), s2 = Math.sin(lat2);
    const num = c1 * c2 * Math.sin(dLon);
    const den = 1 + s1 + s2 + c1 * c2 * Math.cos(dLon) + s1 * s2;
    sum += 2 * Math.atan2(num, den);
  }
  sum = ((sum % FOUR_PI) + FOUR_PI) % FOUR_PI;
  if (sum > 2 * Math.PI) sum -= FOUR_PI;
  return Math.abs(sum);
}

function pointInPlanarRing(x, y, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    if (((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / (yj - yi) + xi)) {
      inside = !inside;
    }
  }
  return inside;
}

function computeInteriorCentroid(ring, isPolar) {
  if (isPolar) return [0, -82];
  const u = unwrapRing(ring);
  const n = u.length;
  if (n === 0) return [0, 0];

  // Area-weighted planar centroid on unwrapped ring
  let area2 = 0, cx = 0, cy = 0;
  let minY = Infinity, maxY = -Infinity;
  for (let i = 0; i < n; i++) {
    const [x0, y0] = u[i];
    const [x1, y1] = u[(i + 1) % n];
    const cross = x0 * y1 - x1 * y0;
    area2 += cross;
    cx += (x0 + x1) * cross;
    cy += (y0 + y1) * cross;
    if (y0 < minY) minY = y0;
    if (y0 > maxY) maxY = y0;
  }

  let bestX = u[0][0];
  let bestY = u[0][1];
  if (Math.abs(area2) > 1e-9) {
    bestX = cx / (3 * area2);
    bestY = cy / (3 * area2);
  }

  // If area centroid is already safely inside the ring, use it
  if (pointInPlanarRing(bestX, bestY, u)) {
    return [Number(normLon(bestX).toFixed(3)), Number(bestY.toFixed(3))];
  }

  // Otherwise, scanline search for the widest interior horizontal chord across 11 latitudes
  let bestSpan = -1;
  let scanX = bestX;
  let scanY = bestY;
  const samples = 11;
  for (let s = 1; s <= samples; s++) {
    const y = minY + ((maxY - minY) * s) / (samples + 1);
    const xs = [];
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const [xi, yi] = u[i];
      const [xj, yj] = u[j];
      if ((yi > y) !== (yj > y)) {
        xs.push(xi + ((y - yi) * (xj - xi)) / (yj - yi));
      }
    }
    xs.sort((a, b) => a - b);
    for (let k = 0; k + 1 < xs.length; k += 2) {
      const span = xs[k + 1] - xs[k];
      if (span > bestSpan) {
        bestSpan = span;
        scanX = (xs[k] + xs[k + 1]) * 0.5;
        scanY = y;
      }
    }
  }
  return [Number(normLon(scanX).toFixed(3)), Number(scanY.toFixed(3))];
}

function buildCountries() {
  const { w, h, features } = RAW_WORLD;
  const list = [];

  for (const f of features) {
    const id = f.id ? String(f.id) : (NULL_ID_MAP[f.name] || f.name.toUpperCase().slice(0, 3));
    const iso = ISO3_BY_ID[id] || id;
    const isPolar = id === "010";

    const polygons = [];
    const holeIndices = [];
    let totalSr = 0;
    let largestRing = null;
    let largestAreaSr = -1;

    let minLon = Infinity, minLat = Infinity, maxLon = -Infinity, maxLat = -Infinity;

    for (const poly of f.polys) {
      let polySr = 0;
      for (let ri = 0; ri < poly.rings.length; ri++) {
        const ring = decodeRing(poly.rings[ri], w, h);
        if (ring.length < 3) continue;
        const ringSr = ringSphericalAreaSr(ring);
        const ringIdx = polygons.length;
        polygons.push(ring);

        if (ri === 0) {
          polySr += ringSr;
          if (ringSr > largestAreaSr) {
            largestAreaSr = ringSr;
            largestRing = ring;
          }
        } else {
          polySr -= ringSr;
          holeIndices.push(ringIdx);
        }

        for (let k = 0; k < ring.length; k++) {
          const [lon, lat] = ring[k];
          if (lon < minLon) minLon = lon;
          if (lon > maxLon) maxLon = lon;
          if (lat < minLat) minLat = lat;
          if (lat > maxLat) maxLat = lat;
        }
      }
      totalSr += Math.max(0, polySr);
    }

    const areaKm2 = Math.round(totalSr * EARTH_RADIUS_KM * EARTH_RADIUS_KM);
    const centroid = largestRing ? computeInteriorCentroid(largestRing, isPolar) : [0, 0];
    const bbox = isPolar
      ? [-180, -90, 180, Number(maxLat.toFixed(3))]
      : [
          Number(minLon.toFixed(3)),
          Number(minLat.toFixed(3)),
          Number(maxLon.toFixed(3)),
          Number(maxLat.toFixed(3)),
        ];

    list.push({
      id,
      name: f.name,
      iso,
      areaKm2,
      centroid,
      bbox,
      polygons,
      holeIndices,
      isPolar,
    });
  }

  return list;
}

export const WORLD_COUNTRIES = buildCountries();

function normalizeKey(str) {
  return String(str)
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ");
}

const LOOKUP = new Map();
for (const c of WORLD_COUNTRIES) {
  LOOKUP.set(normalizeKey(c.id), c);
  LOOKUP.set(normalizeKey(c.iso), c);
  LOOKUP.set(normalizeKey(c.name), c);
}
for (const [alias, targetId] of Object.entries(ALIASES)) {
  const c = LOOKUP.get(normalizeKey(targetId));
  if (c && !LOOKUP.has(normalizeKey(alias))) {
    LOOKUP.set(normalizeKey(alias), c);
  }
}

export function findCountry(queryOrId) {
  if (queryOrId == null) return null;
  const key = normalizeKey(queryOrId);
  if (!key) return null;
  return LOOKUP.get(key) || null;
}
